/**
 * Reads how a client website is built, from the site itself: response headers,
 * cookies, every file the page requests, the markup, runtime globals and the
 * text of its own script bundles and stylesheets. Each technology is listed
 * only when one of its signatures is found; names and groups come from
 * lib/site/techCatalog.json.
 *
 *   node scripts/scan-tech.mjs <sites.json> <outDir> [key …]
 *
 * sites.json: [{ "key": "onaktravel-com", "url": "https://onaktravel.com/" }]
 * Writes <outDir>/tech.json: { key: { tools: [...], why: { name: evidence } } }
 * @author Paşa Quliyev — Cradex Agency
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { chromium } from 'playwright'

const [, , listFile, outDir, ...only] = process.argv
if (!listFile || !outDir) {
  console.error('usage: node scripts/scan-tech.mjs <sites.json> <outDir> [key …]')
  process.exit(1)
}

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const CATALOG = JSON.parse(await readFile(path.join(root, 'lib', 'site', 'techCatalog.json'), 'utf8'))
const ORDER = ['lang', 'platform', 'library', 'design', 'service', 'hosting']
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe'
const sites = JSON.parse(await readFile(listFile, 'utf8')).filter((s) => only.length === 0 || only.includes(s.key))
await mkdir(outDir, { recursive: true })

// name → test(e) returning the evidence (a short string) or a falsy value.
// e: { h: headers, cookies, urls, html, css, js, g: globals, d: DOM facts }
const hit = (text, re) => (re.exec(text) ?? [])[0]?.slice(0, 70)
const RULES = {
  HTML5: (e) => (/^<!doctype html>/i.test(e.html.trimStart()) ? '<!doctype html>' : null),
  CSS3: (e) => (e.d.styles > 0 ? `${e.d.styles} stylesheets / style blocks` : null),
  JavaScript: (e) => (e.d.scripts > 0 ? `${e.d.scripts} scripts` : null),
  // compiled output only proves TypeScript when a .tsx source path survives in it
  TypeScript: (e) => hit(e.js, /[\w/-]+\.tsx["'`:]/),
  PHP: (e) => hit(e.h['x-powered-by'] ?? '', /php/i) || (e.cookies.includes('PHPSESSID') && 'cookie PHPSESSID') || hit(e.urls, /[\w/-]+\.php\b/) || (e.cookies.includes('ci_session') && 'CodeIgniter') || (laravel(e) && 'Laravel') || (wp(e) && 'WordPress') || (/TYPO3/i.test(e.d.generator) && 'TYPO3'),

  WordPress: (e) => wp(e),
  WooCommerce: (e) => hit(e.urls + e.html, /plugins\/woocommerce|wc-ajax|woocommerce-no-js/),
  Elementor: (e) => hit(e.urls + e.html, /plugins\/elementor\/|elementor-frontend|class="elementor /),
  'Elementor Pro': (e) => hit(e.urls, /plugins\/elementor-pro\//),
  WPBakery: (e) => hit(e.urls + e.html, /js_composer|wpb_row|vc_row/),
  Divi: (e) => hit(e.urls + e.html, /themes\/Divi\/|et_pb_section/),
  'Slider Revolution': (e) => hit(e.urls + e.html, /plugins\/revslider|rs-module-wrap/),
  'Contact Form 7': (e) => wp(e) && hit(e.urls + e.html, /plugins\/contact-form-7|wpcf7/),
  'Yoast SEO': (e) => hit(e.html, /Yoast SEO|yoast-schema-graph/),
  'Rank Math SEO': (e) => hit(e.html, /Rank Math|rank-math/),
  WPML: (e) => hit(e.urls + e.html, /sitepress-multilingual-cms|wpml-/),
  Polylang: (e) => hit(e.urls + e.html, /plugins\/polylang|pll-parent-menu-item/),
  'LiteSpeed Cache': (e) => hit(e.urls + e.html, /litespeed-cache|Page generated by LiteSpeed Cache|data-lazyloaded/) || (wp(e) && e.h['x-litespeed-cache'] && 'x-litespeed-cache header'),
  Laravel: (e) => laravel(e),
  Livewire: (e) => hit(e.urls + e.html, /livewire(\.min)?\.js|wire:id=|wire:snapshot/),
  'Inertia.js': (e) => hit(e.html, /id="app" data-page=/),
  CodeIgniter: (e) => e.cookies.includes('ci_session') && 'cookie ci_session',
  'ASP.NET': (e) => hit(e.h['x-powered-by'] ?? '', /asp\.net/i) || hit(e.html, /__VIEWSTATE|__RequestVerificationToken/) || (e.h['x-aspnet-version'] && 'x-aspnet-version') || hit(e.urls, /\.aspx\b|\.ashx\b|WebResource\.axd/),
  TYPO3: (e) => hit(e.d.generator, /TYPO3/i) || hit(e.urls, /typo3(conf|temp)\//),
  'Next.js': (e) => hit(e.urls, /\/_next\/static\//) || (e.h['x-nextjs-cache'] && 'x-nextjs-cache') || hit(e.html, /id="__NEXT_DATA__"|self\.__next_f/),
  React: (e) => (e.g.React && `React ${e.g.React}`) || hit(e.urls, /\/_next\/static\//) || hit(e.js, /react-dom|react\.production|Symbol\.for\("react\.(transitional\.)?element"\)|__reactFiber/) || (e.d.reactAttached && 'React fibers on the DOM'),
  'React Router': (e) => hit(e.js, /react-router|createBrowserRouter|UNSAFE_NavigationContext/),
  'Vue.js': (e) => (e.g.Vue && `Vue ${e.g.Vue}`) || (e.d.vueScoped && 'data-v-* scoped attributes') || hit(e.js, /__vue_app__|vue\.runtime|__VUE__/),
  Nuxt: (e) => hit(e.urls, /\/_nuxt\//) || hit(e.html, /window\.__NUXT__|id="__nuxt"/),
  Angular: (e) => (e.d.ngVersion && `ng-version ${e.d.ngVersion}`) || hit(e.html, /<app-root|_nghost-/),
  Astro: (e) => hit(e.urls, /\/_astro[\w-]*\//) || hit(e.html, /astro-island|data-astro-cid/),
  Svelte: (e) => hit(e.html, /class="[^"]*svelte-[a-z0-9]{5,}/) || hit(e.urls, /\/_app\/immutable\//),
  'Node.js': (e) => hit(e.h['x-powered-by'] ?? '', /express|node/i) || hit(e.urls, /\/_next\/static\//) && null,
  Express: (e) => hit(e.h['x-powered-by'] ?? '', /express/i),
  Wix: (e) => hit(e.d.generator, /Wix/i) || hit(e.urls, /static\.wixstatic\.com|parastorage\.com/),
  'Hostinger Website Builder': (e) => hit(e.d.generator + (e.h['x-powered-by'] ?? ''), /Hostinger\s?Website\s?builder/i) || hit(e.urls, /zyrosite\.com/),
  Tilda: (e) => hit(e.urls, /tildacdn\.(com|info)/),
  OpenCart: (e) => hit(e.html + e.urls, /index\.php\?route=|catalog\/view\/theme/),
  Vite: (e) => hit(e.html, /<script type="module"[^>]+src="[^"]*\/assets\/[\w.-]+-[\w-]{8}\.js"/) || hit(e.js, /__vite__mapDeps|vite\/modulepreload-polyfill|__vitePreload/),
  Webpack: (e) => hit(e.html + e.js, /webpackChunk\w*|__webpack_require__|webpackJsonp/) || hit(e.urls, /\/_next\/static\/chunks\/webpack/),
  MySQL: (e) => ((wp(e) || /index\.php\?route=/.test(e.html)) && 'required by WordPress / OpenCart') || null,
  Firebase: (e) => hit(e.urls, /firebasejs\/|firebaseapp\.com|firebaseio\.com/) || hit(e.js, /firebaseapp\.com|initializeApp\(\{[^}]*apiKey/),
  'Cloud Firestore': (e) => hit(e.urls, /firebase-firestore|firestore\.googleapis\.com/),
  'Firebase Authentication': (e) => hit(e.urls, /firebase-auth|identitytoolkit\.googleapis\.com/),
  Supabase: (e) => hit(e.urls, /supabase-js|\.supabase\.co/) || hit(e.js, /\.supabase\.co/),

  jQuery: (e) => (e.g.jQuery && `jQuery ${e.g.jQuery}`) || hit(e.urls, /jquery[.-]?[\d.]*(\.min)?\.js/i),
  'jQuery UI': (e) => hit(e.urls, /jquery[.-]ui/i) || (e.g.jQueryUI && `jQuery UI ${e.g.jQueryUI}`),
  'Alpine.js': (e) => (e.g.Alpine && 'window.Alpine') || hit(e.urls, /alpine(js)?[@.\w-]*\.js|alpinejs/) || (e.d.xData && /livewire/.test(e.urls + e.html) && 'x-data with Livewire'),
  Swiper: (e) => hit(e.urls, /swiper[\w.@/-]*\.(js|css)/i) || (e.g.Swiper && 'window.Swiper') || hit(e.html, /class="[^"]*swiper-(wrapper|slide)/) || hit(e.js, /swiper-slide-active/),
  'Owl Carousel': (e) => hit(e.urls, /owl\.carousel/i) || hit(e.html, /class="[^"]*owl-carousel/),
  Slick: (e) => hit(e.urls, /slick(\.min)?\.(js|css)|slick-carousel/i) || hit(e.html, /class="[^"]*slick-slider/),
  GSAP: (e) => (e.g.gsap && `gsap ${e.g.gsap}`) || hit(e.urls, /gsap[\w.@/-]*\.js|TweenMax/i) || hit(e.js, /gsap\.registerPlugin|_gsScope|GreenSockGlobals/),
  ScrollTrigger: (e) => hit(e.urls, /ScrollTrigger/i) || (e.g.ScrollTrigger && 'window.ScrollTrigger') || hit(e.js, /ScrollTrigger\.(create|refresh)/),
  AOS: (e) => hit(e.urls, /\baos(\.min)?\.(js|css)|aos@/i) || hit(e.html, /data-aos="/),
  'WOW.js': (e) => hit(e.urls, /wow(\.min)?\.js/i),
  Fancybox: (e) => hit(e.urls, /fancybox/i) || hit(e.html, /data-fancybox/),
  'Magnific Popup': (e) => hit(e.urls, /magnific[.-]popup/i),
  Lightcase: (e) => hit(e.urls, /lightcase/i),
  Isotope: (e) => hit(e.urls, /isotope/i),
  'Three.js': (e) => (e.g.THREE && 'window.THREE') || hit(e.urls, /three(\.module)?(\.min)?\.js|three@/i) || hit(e.js, /THREE\.WebGLRenderer|WebGLRenderer.{0,200}PerspectiveCamera/),
  Lottie: (e) => (e.g.lottie && 'window.lottie') || hit(e.urls, /lottie|bodymovin/i),
  'Framer Motion': (e) => hit(e.js, /framer-motion|motion-dom|data-framer-appear|MotionConfigContext/),
  Lenis: (e) => hit(e.urls, /lenis/i) || hit(e.html, /class="[^"]*\blenis\b/) || hit(e.js, /lenis-smooth|lenis lenis/),
  Axios: (e) => (e.g.axios && 'window.axios') || hit(e.urls, /axios[\w.@/-]*\.js/i) || hit(e.js, /isAxiosError|AxiosError/),
  i18next: (e) => hit(e.urls, /i18next/i) || hit(e.js, /i18next|initReactI18next/),
  Select2: (e) => hit(e.urls, /select2/i),
  Flatpickr: (e) => hit(e.urls, /flatpickr/i) || hit(e.html, /class="[^"]*flatpickr-/),
  'Air Datepicker': (e) => hit(e.urls, /(air-)?datepicker(\.min)?\.js/i),
  Toastr: (e) => hit(e.urls, /toastr/i),
  SweetAlert2: (e) => hit(e.urls, /sweetalert/i) || (e.g.Swal && 'window.Swal'),
  'Chart.js': (e) => hit(e.urls, /chart(\.umd)?(\.min)?\.js|chart\.js/i) || (e.g.Chart && 'window.Chart'),
  Leaflet: (e) => hit(e.urls, /leaflet/i),
  'Typed.js': (e) => hit(e.urls, /typed(\.min)?\.js|typed\.js/i),
  Lazysizes: (e) => hit(e.urls, /lazysizes/i),
  'Pace.js': (e) => hit(e.urls, /\bpace(\.min)?\.js/i),
  Modernizr: (e) => hit(e.urls, /modernizr/i),
  'Popper.js': (e) => hit(e.urls, /popper/i),
  'Moment.js': (e) => hit(e.urls, /moment(\.min|-with-locales)?[\w.]*\.js/i) || (e.g.moment && 'window.moment'),
  Inputmask: (e) => hit(e.urls, /inputmask/i),
  SlickNav: (e) => hit(e.urls, /slicknav/i),
  'Tesseract.js': (e) => hit(e.urls, /tesseract/i),
  SheetJS: (e) => hit(e.urls, /xlsx[\w.@/-]*\.js/i),

  'Tailwind CSS': (e) => hit(e.urls, /cdn\.tailwindcss\.com|tailwind[\w.-]*\.css/i) || hit(e.css + e.html, /--tw-[a-z-]+:|\*,::before,::after\{--tw-/),
  Bootstrap: (e) => hit(e.urls, /bootstrap[\w.@/-]*\.(js|css)/i) || (e.g.bootstrap && `Bootstrap ${e.g.bootstrap}`) || hit(e.css, /--bs-[a-z-]+:|\.navbar-toggler\b/),
  'Animate.css': (e) => hit(e.urls, /animate(\.min)?\.css|animate\.css/i) || hit(e.css, /\.animate__animated\b/),
  'Google Fonts': (e) => hit(e.urls, /fonts\.googleapis\.com\/css2?\?family=[\w+]+|fonts\.gstatic\.com/),
  'Font Awesome': (e) => hit(e.urls, /font-?awesome|fontawesome|use\.fontawesome\.com|\/all(\.min)?\.css/i) || hit(e.css, /Font Awesome \d/),
  'Bootstrap Icons': (e) => hit(e.urls, /bootstrap-icons/i),
  'Line Awesome': (e) => hit(e.urls, /line-awesome/i),
  'Remix Icon': (e) => hit(e.urls, /remixicon/i),
  Boxicons: (e) => hit(e.urls, /boxicons/i),
  'Material Icons': (e) => hit(e.urls, /Material\+(Icons|Symbols)|material-icons/i),
  Lucide: (e) => hit(e.html, /class="[^"]*\blucide lucide-/) || hit(e.urls, /lucide/i),

  'Google Analytics': (e) => hit(e.urls, /google-analytics\.com|googletagmanager\.com\/gtag\/js\?id=(G|UA)-[\w-]+|analytics\.google\.com/),
  'Google Tag Manager': (e) => hit(e.urls, /googletagmanager\.com\/gtm\.js\?id=GTM-\w+/),
  'Google Ads': (e) => hit(e.urls, /gtag\/js\?id=AW-\d+|googleads\.g\.doubleclick\.net|googleadservices\.com/),
  'Meta Pixel': (e) => hit(e.urls, /connect\.facebook\.net\/[\w_]+\/fbevents\.js|facebook\.com\/tr\b/),
  'Yandex Metrica': (e) => hit(e.urls, /mc\.yandex\.(ru|com)/),
  'Microsoft Clarity': (e) => hit(e.urls, /clarity\.ms/),
  Hotjar: (e) => hit(e.urls, /hotjar\.com/),
  'TikTok Pixel': (e) => hit(e.urls, /analytics\.tiktok\.com/),
  'Google Maps': (e) => hit(e.urls + e.html, /maps\.googleapis\.com|google\.com\/maps\/embed|maps\.google\.com\/maps\?/),
  'Yandex Maps': (e) => hit(e.urls + e.html, /api-maps\.yandex|yandex\.[a-z]+\/map-widget/),
  reCAPTCHA: (e) => hit(e.urls, /recaptcha/i),
  'Cloudflare Turnstile': (e) => hit(e.urls, /challenges\.cloudflare\.com\/turnstile/),
  YouTube: (e) => hit(e.urls + e.html, /youtube(-nocookie)?\.com\/embed\/|youtube\.com\/iframe_api/),
  'Tawk.to': (e) => hit(e.urls, /tawk\.to/),
  JivoChat: (e) => hit(e.urls, /jivo(site|chat)|code\.jivo/i),
  Elfsight: (e) => hit(e.urls, /elfsight/i),
  'Facebook SDK': (e) => hit(e.urls, /connect\.facebook\.net\/[\w_]+\/sdk\.js/),
  'JSON-LD (Schema.org)': (e) => (e.d.jsonLd > 0 ? `${e.d.jsonLd} application/ld+json block(s)` : null),
  PWA: (e) => (e.d.manifest && e.d.serviceWorker ? 'web manifest + service worker' : null),

  Vercel: (e) => (e.h['x-vercel-id'] && 'x-vercel-id') || hit(e.h.server ?? '', /vercel/i),
  Netlify: (e) => hit(e.h.server ?? '', /netlify/i) || (e.h['x-nf-request-id'] && 'x-nf-request-id'),
  Cloudflare: (e) => (e.h['cf-ray'] && 'cf-ray') || hit(e.h.server ?? '', /cloudflare/i),
  LiteSpeed: (e) => hit(`${e.h.server ?? ''} ${e.h['x-turbo-charged-by'] ?? ''} ${e.h['x-powered-by'] ?? ''}`, /litespeed|OLS/i) || (e.h['x-litespeed-cache'] && 'x-litespeed-cache'),
  Nginx: (e) => hit(e.h.server ?? '', /nginx/i),
  Apache: (e) => hit(e.h.server ?? '', /apache/i),
  'Google Cloud': (e) => hit(e.h.server ?? '', /Google Frontend|gws/),
  BunnyCDN: (e) => hit(e.h.server ?? '', /bunnycdn/i),
  Hostinger: (e) => hit(`${e.h.server ?? ''} ${e.h.platform ?? ''}`, /hcdn|hostinger/i),
  jsDelivr: (e) => hit(e.urls, /cdn\.jsdelivr\.net/),
  cdnjs: (e) => hit(e.urls, /cdnjs\.cloudflare\.com/),
  unpkg: (e) => hit(e.urls, /unpkg\.com/),
}

function wp(e) {
  return hit(e.urls + e.html, /\/wp-content\/(themes|plugins|uploads)\/|\/wp-includes\//) || hit(e.d.generator, /WordPress/i)
}
function laravel(e) {
  if (e.cookies.includes('laravel_session')) return 'cookie laravel_session'
  const session = e.cookies.find((c) => /_session$/.test(c))
  if (e.cookies.includes('XSRF-TOKEN') && session) return `cookies XSRF-TOKEN + ${session}`
  return hit(e.urls + e.html, /livewire(\.min)?\.js|wire:id=/) ? 'Livewire' : null
}

function facts() {
  const w = window
  const some = (sel) => document.querySelectorAll(sel).length
  const first400 = [...document.querySelectorAll('body *')].slice(0, 600)
  return {
    g: {
      jQuery: w.jQuery?.fn?.jquery ?? null,
      jQueryUI: w.jQuery?.ui?.version ?? null,
      bootstrap: w.bootstrap?.Tooltip?.VERSION ?? w.jQuery?.fn?.tooltip?.Constructor?.VERSION ?? null,
      React: w.React?.version ?? null,
      Vue: w.Vue?.version ?? null,
      gsap: w.gsap?.version ?? null,
      ScrollTrigger: Boolean(w.ScrollTrigger),
      Swiper: Boolean(w.Swiper),
      Alpine: Boolean(w.Alpine),
      axios: Boolean(w.axios),
      THREE: Boolean(w.THREE),
      lottie: Boolean(w.lottie || w.bodymovin),
      Swal: Boolean(w.Swal),
      Chart: Boolean(w.Chart),
      moment: Boolean(w.moment),
    },
    d: {
      generator: [...document.querySelectorAll('meta[name="generator"]')].map((m) => m.content).join(' | '),
      scripts: document.scripts.length,
      styles: some('link[rel="stylesheet"], style'),
      jsonLd: some('script[type="application/ld+json"]'),
      manifest: Boolean(document.querySelector('link[rel="manifest"]')),
      serviceWorker: Boolean(navigator.serviceWorker?.controller),
      ngVersion: document.querySelector('[ng-version]')?.getAttribute('ng-version') ?? null,
      xData: some('[x-data]') > 0,
      vueScoped: first400.some((n) => [...n.attributes].some((a) => /^data-v-[a-f0-9]{6,}$/.test(a.name))),
      reactAttached: first400.some((n) => Object.keys(n).some((k) => k.startsWith('__reactFiber') || k.startsWith('__reactContainer'))),
    },
  }
}

async function scan(browser, site) {
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, locale: 'az-AZ', ignoreHTTPSErrors: true })
  const page = await ctx.newPage()
  const requests = new Set()
  page.on('request', (r) => requests.add(r.url()))
  const out = { key: site.key }
  try {
    const res = await page.goto(site.url, { waitUntil: 'domcontentloaded', timeout: 90000 })
    await page.waitForLoadState('load', { timeout: 30000 }).catch(() => {})
    await page.waitForLoadState('networkidle', { timeout: 12000 }).catch(() => {})
    // scroll once: sliders, maps and embeds below the fold load on demand
    await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight && y < 9000; y += 900) { scrollTo(0, y); await new Promise((r) => setTimeout(r, 250)) } scrollTo(0, 0) }).catch(() => {})
    await page.waitForTimeout(2500)

    const e = await page.evaluate(facts)
    e.h = res?.headers() ?? {}
    e.cookies = (await ctx.cookies()).map((c) => c.name)
    e.html = await page.content()
    if (/please wait while your request is being verified|additional security check is required/i.test(e.html)) throw new Error('host verification page, not the site')
    e.urls = [...requests].join('\n')

    // the site's own bundles and stylesheets, read as text (third-party hosts are judged by URL alone)
    const origin = new URL(page.url()).origin
    const own = [...requests].filter((u) => u.startsWith(origin) && /\.(js|mjs|css)(\?|$)/.test(u))
    const read = async (list, cap) => {
      let text = ''
      for (const u of list) {
        if (text.length > cap) break
        const body = await ctx.request.get(u, { timeout: 20000 }).then((r) => (r.ok() ? r.text() : '')).catch(() => '')
        text += `\n/* ${u} */\n${body.slice(0, 2_500_000)}`
      }
      return text
    }
    e.js = await read(own.filter((u) => /\.m?js(\?|$)/.test(u)).slice(0, 14), 7_000_000)
    e.css = await read(own.filter((u) => /\.css(\?|$)/.test(u)).slice(0, 8), 3_000_000)

    out.why = {}
    for (const [name, test] of Object.entries(RULES)) {
      let found = null
      try { found = test(e) } catch { found = null }
      if (found) out.why[name] = String(found)
    }
    // React through Next.js runs on Node.js
    if (out.why['Next.js'] && !out.why['Node.js']) out.why['Node.js'] = 'Next.js server runtime'
    // a .php address alone may be someone else's script; the platform proves PHP on its own
    if (/\.php$/.test(out.why.PHP ?? '') && !out.why.WordPress && !out.why.Laravel && !out.why.CodeIgniter && !out.why.TYPO3) delete out.why.PHP
    // what a CMS or site builder ships for its own editor is not the project's stack
    const internals = out.why.WordPress
      ? ['React', 'Webpack', 'TypeScript']
      : out.why['Hostinger Website Builder']
        ? ['Astro', 'Vue.js']
        : out.why.Wix
          ? Object.keys(out.why).filter((n) => n !== 'Wix' && !['lang', 'service', 'hosting'].includes(CATALOG[n])).concat('TypeScript')
          : []
    for (const n of internals) delete out.why[n]
    out.tools = Object.keys(out.why).sort((a, b) => ORDER.indexOf(CATALOG[a]) - ORDER.indexOf(CATALOG[b]))
  } catch (err) {
    out.error = String(err.message).split('\n')[0]
  }
  await ctx.close()
  console.log(`${out.error ? 'FAIL' : 'ok  '} ${site.key.padEnd(30)} ${out.error ?? out.tools.join(', ')}`)
  return out
}

for (const name of Object.keys(RULES)) if (!CATALOG[name]) throw new Error(`"${name}" is missing from lib/site/techCatalog.json`)

const browser = await chromium.launch({ executablePath: CHROME })
const queue = [...sites]
const results = {}
await Promise.all(
  Array.from({ length: 4 }, async () => {
    for (let s = queue.shift(); s; s = queue.shift()) results[s.key] = await scan(browser, s)
  })
)
await browser.close()
